SourceCode.Declaration:
/// <summary>
/// One line of a handheld menu (HSMobileOpsMenu), in LineNum order: an app module, or another
/// menu opened as a sub-menu. Menu access (HSMobileOpsUserModulePermission) still decides which
/// modules a worker sees; a sub-menu with nothing left in it is not shown.
///
/// SubMenuId deliberately has no table relation to HSMobileOpsMenu: with two relations to the
/// same table, the form's line grid joined on both and showed nothing. The form's control
/// supplies the lookup instead (HSMobileOpsMenu form, Line_SubMenuId.lookup).
/// </summary>
public class HSMobileOpsMenuLine extends common
{
}

Method.Source:
public void insert()
{
    HSMobileOpsMenuLine last;

    if (!this.Sequence)
    {
        select maxOf(LineNum) from last
            where last.MenuRecId == this.MenuRecId;
        this.Sequence = real2int(last.LineNum) + 10;
    }
    this.LineNum = this.Sequence;
    if (this.LineType == HSMobileOpsMenuLineType::Module)
    {
        this.SubMenuId = '';
    }
    this.setOpens();
    super();
}

public void update()
{
    this.LineNum = this.Sequence;
    if (this.LineType == HSMobileOpsMenuLineType::Module)
    {
        this.SubMenuId = '';
    }
    this.setOpens();
    super();
}

/// <summary>
/// Opens, for the form's grid: the module's name, or the sub-menu's ID and name. Stored
/// rather than a display method, which shows blank on this environment's forms.
/// </summary>
public void setOpens()
{
    HSMobileOpsMenu subMenu;

    if (this.LineType == HSMobileOpsMenuLineType::SubMenu)
    {
        subMenu = HSMobileOpsMenu::find(this.SubMenuId);
        this.Opens = subMenu.RecId ? strFmt('%1 - %2', subMenu.MenuId, subMenu.Name) : this.SubMenuId;
    }
    else
    {
        this.Opens = enum2Str(this.Module);
    }
}

/// <summary>
/// A sub-menu line must open an existing menu that does not lead back to this one (the
/// handheld would loop), and a module is listed once per menu.
/// </summary>
public boolean validateWrite()
{
    HSMobileOpsMenu     parent = HSMobileOpsMenu::findRecId(this.MenuRecId);
    HSMobileOpsMenuLine duplicate;
    boolean             ok = super();

    if (ok && this.LineType == HSMobileOpsMenuLineType::SubMenu)
    {
        if (!this.SubMenuId)
        {
            ok = checkFailed('Select the menu this line opens.');
        }
        else if (!HSMobileOpsMenu::find(this.SubMenuId).RecId)
        {
            ok = checkFailed(strFmt('Menu %1 does not exist.', this.SubMenuId));
        }
        else if (this.SubMenuId == parent.MenuId || HSMobileOpsMenuLine::leadsTo(this.SubMenuId, parent.MenuId, 0))
        {
            ok = checkFailed(strFmt('Menu %1 leads back to %2, so it cannot be a sub-menu of it.', this.SubMenuId, parent.MenuId));
        }
    }
    if (ok && this.Sequence)
    {
        select firstOnly RecId from duplicate
            where duplicate.MenuRecId == this.MenuRecId
               && duplicate.LineNum   == this.Sequence
               && duplicate.RecId     != this.RecId;
        if (duplicate.RecId)
        {
            ok = checkFailed(strFmt('Sequence %1 is already used on this menu.', this.Sequence));
        }
    }
    if (ok && this.LineType == HSMobileOpsMenuLineType::Module)
    {
        select firstOnly RecId from duplicate
            where duplicate.MenuRecId == this.MenuRecId
               && duplicate.LineType  == HSMobileOpsMenuLineType::Module
               && duplicate.Module    == this.Module
               && duplicate.RecId     != this.RecId;
        if (duplicate.RecId)
        {
            ok = checkFailed(strFmt('%1 is already on this menu.', this.Module));
        }
    }
    return ok;
}

/// <summary>
/// Whether menu _fromMenuId opens _targetMenuId, directly or through its sub-menus.
/// </summary>
public static boolean leadsTo(str _fromMenuId, str _targetMenuId, int _depth)
{
    HSMobileOpsMenu     fromMenu = HSMobileOpsMenu::find(_fromMenuId);
    HSMobileOpsMenuLine line;

    if (_depth > 20)
    {
        return true;
    }
    if (!fromMenu.RecId)
    {
        return false;
    }
    while select SubMenuId from line
        where line.MenuRecId == fromMenu.RecId
           && line.LineType  == HSMobileOpsMenuLineType::SubMenu
    {
        if (line.SubMenuId == _targetMenuId || HSMobileOpsMenuLine::leadsTo(line.SubMenuId, _targetMenuId, _depth + 1))
        {
            return true;
        }
    }
    return false;
}
